source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for x in row:
            freq[x] = freq.get(x, 0) + 1
    bg = max(freq, key=freq.get)
    border_rows = [0, h - 1]
    line_color = None
    bar_cells = {}
    for r in border_rows:
        counts = {}
        for x in grid[r]:
            if x != bg:
                counts[x] = counts.get(x, 0) + 1
        if counts:
            c = max(counts, key=counts.get)
            line_color = c if line_color is None else line_color
            bar_cells[r] = [i for i, x in enumerate(grid[r]) if x == line_color]
    dots = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
            if grid[r][c] != bg and grid[r][c] != line_color
            and not (r in border_rows and grid[r][c] == line_color)]
    if not dots or line_color is None:
        return out
    ink = dots[0][2]
    k = len(dots)
    for r in border_rows:
        cols = bar_cells.get(r, [])
        cols = cols[-k:]
        step = 1 if r == 0 else -1
        for c in cols:
            rr = r + step
            while 0 <= rr < h:
                if grid[rr][c] not in (bg, line_color):
                    out[rr][c] = 4
                    break
                out[rr][c] = ink
                rr += step
    for r, c, _ in dots:
        out[r][c] = 4
    return out
